package com.prima.factory.service;
import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import com.prima.factory.mapper.MonitoringMapper;
@Service public class MonitoringService { private final MonitoringMapper mapper; public MonitoringService(MonitoringMapper mapper){this.mapper=mapper;} public List<Map<String,Object>> equipment(){return mapper.currentEquipment();} public List<Map<String,Object>> collection(){return mapper.collectionHealth();} public List<Map<String,Object>> products(){return mapper.products();} public Map<String,Object> dashboard(){var eq=equipment(); long running=eq.stream().filter(e->"RUNNING".equals(e.get("status"))).count(); long alarm=eq.stream().filter(e->String.valueOf(e.get("status")).contains("FAULT")).count(); return Map.of("equipment",eq,"running",running,"alarms",alarm,"generatedAt",java.time.OffsetDateTime.now());} public MonitoringMapper mapper(){return mapper;} @Transactional public void createEquipment(Map<String,Object>b){mapper.insertEquipment(b);}@Transactional public void updateEquipment(long id,Map<String,Object>b){mapper.updateEquipment(id,b);}@Transactional public void deactivateEquipment(long id){mapper.deactivateEquipment(id);} }
